function e(r,t=0){if(r==null||r==="")return"—";const n=Number(r);return Number.isNaN(n)?"—":n.toFixed(t)}function i(r,t=1){if(r==null||r==="")return"—";const n=Number(r);return Number.isNaN(n)?"—":`${(n*100).toFixed(t)}%`}function o(r){const t=Number(r);return Number.isFinite(t)?t>=1e3?`${(t/1e3).toFixed(2)}s`:`${Math.round(t)}ms`:"—"}function u(r){const t=new Date(r).getTime();if(!Number.isFinite(t))return"";const n=Math.max(0,Date.now()-t);return n<6e4?"刚刚":n<36e5?`${Math.floor(n/6e4)} 分钟前`:n<864e5?`${Math.floor(n/36e5)} 小时前`:`${Math.floor(n/864e5)} 天前`}function f(r){return r?r.replace("evidence_","ev"):"—"}export{u as a,o as m,e as n,i as p,f as s};
